mapper.select:
SELECT wr.id, wr.user_id, wr.record_date, wr.weight, wr.source, wr.recorded_at
FROM weight_records wr
INNER JOIN (
    SELECT record_date, MAX(id) AS latest_id
    FROM weight_records
    WHERE user_id = #{userId}
      AND record_date BETWEEN #{startDate} AND #{endDate}
    GROUP BY record_date
) latest ON latest.latest_id = wr.id
WHERE wr.user_id = #{userId}
ORDER BY wr.record_date ASC
